package pe.pisacoma.iglesia.data.content

import kotlinx.serialization.Serializable
import pe.pisacoma.iglesia.data.AppJson
import java.util.Locale

/** One downloadable file, as listed by content/manifest.json (generated by tools/sync-content.mjs). */
@Serializable
data class ContentFile(val path: String, val bytes: Long, val pack: String)

/** The list of every downloadable file with its size and pack; bundled in the APK as `manifest.json`. */
@Serializable
data class Manifest(val generated: String = "", val files: List<ContentFile> = emptyList()) {
    private val index: Map<String, ContentFile> by lazy { files.associateBy { it.path } }

    val totalBytes: Long get() = files.sumOf { it.bytes }

    fun bytesOf(packs: Collection<String>): Long = files.filter { it.pack in packs }.sumOf { it.bytes }

    /** The files a mode downloads up front: everything, the essential packs, or nothing. */
    fun filesFor(mode: ContentMode): List<ContentFile> = when (mode) {
        ContentMode.TODO -> files
        ContentMode.ESENCIAL -> files.filter { it.pack in Packs.ESSENTIAL }
        ContentMode.USO, ContentMode.EN_LINEA -> emptyList()
    }

    fun byPath(path: String): ContentFile? = index[path]

    companion object {
        fun parse(json: String): Manifest = AppJson.decodeFromString(serializer(), json)
    }
}

/** The four choices of the first open (pref `contenido.modo`). */
enum class ContentMode(val value: String, val label: String) {
    TODO("todo", "Descargar todo"),
    ESENCIAL("esencial", "Descargar lo esencial"),
    USO("uso", "Solo lo que uso"),
    EN_LINEA("en-linea", "Mantener solo en línea");

    /** Downloads packs up front. */
    val downloads: Boolean get() = this == TODO || this == ESENCIAL

    /** Keeps what it reads on disk. */
    val persists: Boolean get() = this != EN_LINEA

    companion object {
        fun of(value: String?): ContentMode? = entries.firstOrNull { it.value == value }
    }
}

/** The packs the manifest groups files into, in display order. */
object Packs {
    val ORDER = listOf("himnario-es", "himnario-pt", "biblia", "escuela", "buscar", "egw")
    val ESSENTIAL = setOf("himnario-es", "biblia", "escuela", "buscar")

    fun label(id: String): String = when (id) {
        "himnario-es" -> "Himnario Adventista"
        "himnario-pt" -> "Hinários (portugués)"
        "biblia" -> "Biblia Reina-Valera 1960"
        "escuela" -> "Escuela Sabática y Quiz"
        "buscar" -> "Índice de búsqueda"
        "egw" -> "25 libros de Ellen G. White"
        else -> id
    }
}

/** «5,9 MB» under ten megabytes, «29 MB» above; decimal megabytes, Spanish comma. */
fun formatMb(bytes: Long): String {
    if (bytes <= 0) return "0 MB"
    val mb = bytes / 1_000_000.0
    return if (mb < 10) String.format(Locale.ROOT, "%.1f", mb).replace('.', ',') + " MB" else "${Math.round(mb)} MB"
}
